from collections import deque,defaultdict
R=C=30
# 4/8 connected components of color1
for conn in [4,8]:
    seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
       if orig[r][c]!=1 or (r,c) in seen: continue
       q=[(r,c)];seen.add((r,c)); comp=[]
       while q:
        x,y=q.pop();comp.append((x,y))
        for dx in [-1,0,1]:
         for dy in [-1,0,1]:
