          if 0<=z[0]<R and 0<=z[1]<C and orig[z[0]][z[1]]==1 and z not in seen:seen.add(z);q.append(z)
       comps.append(comp)
    print('conn',conn,'components',len(comps))
    for k,comp in enumerate(sorted(comps,key=len,reverse=True)):
      ad=defaultdict(int)
