       for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        rr,cc=r+dr,c+dc
        if 0<=rr<R and 0<=cc<C and orig[rr][cc] in (0,9):ad[orig[rr][cc]]+=1
